      "conditions_treated": null,
      "description": "Eat Shed Glow® is a nutrition education and weight loss coaching practice founded by Coco Pierrel, Certified Integrative Nutritionist, serving clients in NYC, Connecticut, and virtually worldwide.\n\nThe method teaches clients to unlearn dieting and relearn how to eat, for weight loss that lasts. No calorie counting, no food rules, no eliminated food groups.\n\nCoco provides nutrition support for people on GLP-1 medications including Ozempic, Wegovy, Mounjaro, and Zepbound: protein targets, muscle preservation, managing side effects with food, and building habits that hold when the medication stops. She also specialises in perimenopause and menopause weight loss.\n\nFeatured in Harper's Bazaar, Real Simple, NBC Select, Delish, NewBeauty, Healthline, and the Daily Mail.\n\nNutrition coaching provided alongside your prescribing physician.",
